\section{Related Work}
\label{sec:related-work}

\paragraph{Self-Consistency and Extensions.}
Self-Consistency (SC) selects the most frequent answer across multiple chain-of-thought traces \citep{wang2023sc}. Universal SC extends this to free-form generation by using an LLM to select among diverse candidates \citep{chen2024usc}. Confidence-weighted variants assign non-uniform weights to traces \citep{taubenfeld2025cisc}, and DiVeRSe combines diverse prompts with a step-aware verifier \citep{li2023diverse}. Reasoning-aware sampling refines SC further by using textual quality indicators \citep{wan2024rasc} or evidence sufficiency \citep{kim2026reasc} to filter traces without training a separate model. \citet{loo2025reevaluating} show that SC gains plateau early and decline for strong models. Our Condorcet analysis explains this pattern: same-model traces yield Fleiss' $\kappa$ of 0.21--0.82, compressing $K_{\text{eff}}$ to 1.2--3.6 for $K = 12$ (\S\ref{sec:effective-k}). SICA shares SC's sampling setup but replaces majority voting with MAX-SAT aggregation over symbolic constraints. The substitution is regime-dependent: self-extracted constraints provide gains only when SC accuracy falls in a narrow band (${\sim}$50--55\%).

\paragraph{Neuro-Symbolic Reasoning.}
Logic-LM \citep{pan2023logiclm} translates natural language problems into first-order logic (FOL) and delegates solving to an external prover. LINC \citep{olausson2023linc} follows a similar pipeline but documents ${\sim}$40\% translation errors on FOLIO. More recent systems extend this integration: DyLoS \citep{xu2026dylos} adaptively selects solver types, Aristotle \citep{li2025aristotle} applies logic-complete decomposition, FoVer \citep{wang2025fover} trains dedicated FOL verifiers, and LogicAgent \citep{luo2025logicagent} employs multi-perspective grounding. Each introduces capabilities beyond the reasoning model itself, whether through trained extractors, external provers, or multi-component pipelines. \citet{amonkar2025realitycheck} show that LLM formalization quality degrades with problem complexity, consistent with our extraction-quality findings. SICA asks whether the \emph{same} model can extract useful constraints from its own traces without additional machinery. Our oracle controls ($+14.22$\,pp on FOLIO, $+11.50$\,pp on ProofWriter; \S\ref{sec:oracle-design}) confirm the aggregation mechanism is sound when constraints are discriminative; the failure localizes to self-extraction quality, not the symbolic approach. This oracle-replacement methodology follows \citet{press2023compositionality}, who use oracle sub-questions to isolate pipeline bottlenecks.

\paragraph{Test-Time Compute and Trace Diversity.}
Scaling test-time computation through additional reasoning traces offers an alternative to parameter scaling \citep{snell2025scaling}. Reasoning-specialized models such as DeepSeek-R1 \citep{guo2025deepseekr1} internalize extended chain-of-thought through reinforcement learning, and diversity-aware training explicitly optimizes for trace variety at test time \citep{diverseaware2026}. These approaches share a common challenge: independent reasoning attempts from the same model collapse into correlated solutions. Our Condorcet/$K_{\text{eff}}$ analysis (\S\ref{sec:condorcet}) provides a theoretical framework for this collapse. Same-model sampling creates correlated voters, and the effective ensemble size $K_{\text{eff}}$ is bounded by inter-trace agreement regardless of how many traces $K$ are sampled. Reasoning models intensify this problem: QwQ-32B achieves a multi-candidate rate $C_0$ of only 2.6\%, reducing any aggregation method to the unanimous output.

\paragraph{Verification and Reranking.}
Trained verifiers offer a data-driven alternative to self-extraction. Outcome reward models (ORMs) score complete solutions \citep{cobbe2021gsm8k}, process reward models (PRMs) assign step-level scores and outperform outcome-level verification \citep{lightman2024prm}, and Math-Shepherd automates process supervision without human annotations \citep{wang2024mathshepherd}. Multi-agent debate refines answers through iterative natural-language discussion \citep{liang2023encouraging,du2023improving}, a paradigm distinct from SICA's one-shot symbolic aggregation. Self-correction methods attempt refinement without external feedback \citep{huang2024selfcorrect,madaan2023selfrefine}, but \citet{stechly2025selfverification} show that LLM self-verification degrades performance while sound external verification yields gains. Their finding parallels our capability trap in the high-accuracy regime. Both trained verifiers and SICA face extraction-quality challenges, but trained approaches may prove more robust because they learn discriminative patterns from data rather than relying on the same model's symbolic capabilities. The consistent pattern across this literature is that reliably improving on majority voting requires information beyond the reasoning model's own outputs (\S\ref{sec:remediation}).

\paragraph{Condorcet Jury Theorem and Ensemble Diversity.}
The Condorcet Jury Theorem (CJT) \citep{condorcet1785} establishes that majority voting among independent voters, each correct with probability $p > 0.5$, converges to correctness as the number of voters grows. \citet{austensmith1996} extend this result to information aggregation under strategic conditions. \citet{ladha1992correlated} prove that correlated voters reduce the effective ensemble size, a result we operationalize as $K_{\text{eff}} = K / (1 + (K{-}1) \cdot \kappa)$ in \S\ref{sec:condorcet}. \citet{lefort2024condorcet_llm} apply the CJT framework to LLM ensemble sentiment classification and document independence violations when all ensemble members share the same architecture. We extend this line of work to reasoning-trace aggregation, measuring $\kappa$ and $K_{\text{eff}}$ across 10 model-dataset conditions (\S\ref{sec:effective-k}). Fleiss' $\kappa$ \citep{fleiss1971kappa} serves as our inter-rater agreement metric, connecting the voting-theory framework to a concrete diagnostic for when symbolic aggregation can improve over majority voting.

\section{Discussion}
\label{sec:discussion}

The oracle experiments causally isolate the failure source: replacing only the constraint source while holding all pipeline components fixed yields $+14.22$\,pp on FOLIO ($p = 2.0 \times 10^{-7}$) and $+11.50$\,pp on ProofWriter ($p = 9.21 \times 10^{-15}$). Aggregation is not the bottleneck; constraint extraction quality is. Three failure modes explain why self-extraction works only in a narrow band. Type A (SC $\geq$ $\sim$60\%): consistent traces produce constraints that mirror model answers. Confirmation bias reaches 62.3\% (Qwen2.5-14B), override precision drops to 28.6\%, and only 8.2\% of constraints are Z3-discriminative (95\% CI [7.6, 8.8]). Even ICL with gold FOL examples cannot break this pattern ($\Delta = +0.54$\,pp, n.s.), because the high-accuracy traces themselves lack the diversity that constraints need to exploit. Type C (SC $\leq$ $\sim$40\%): traces are predominantly wrong, so constraints encode incorrect reasoning as formal rules. The solver amplifies rather than corrects these errors ($\Delta = -4.67$\,pp on PW-D5). Type B: domains that resist FOL formalization yield non-discriminative constraints regardless of accuracy. The Goldilocks zone ($\sim$50--55\% SC) requires both sufficient diversity (traces disagree) and partial correctness (some constraints are right). Six remediation strategies all fail to widen this zone (\S\ref{sec:interventions}), confirming the boundaries are structural. Published methods achieving positive results \citep{xu2026dylos, li2025aristotle, wang2025fover, luo2025logicagent} each introduce capabilities beyond the reasoning model itself; trained extractors and external provers remain viable paths to the oracle ceiling.

For practitioners, $C_0$ and SC accuracy form a two-dimensional diagnostic. Low $C_0$ ($< 5\%$) indicates degenerate conditions. High $C_0$ with high SC ($\geq$ 60\%) activates the Type A trap. High $C_0$ with very low SC ($\leq$ 40\%) risks Type C harm. Only high $C_0$ with moderate SC ($\sim$50--55\%) is favorable, and even here self-extraction captures only 34.5\% of the oracle ceiling. Constraint extraction adds 48.7\% overhead; this cost is justified only in the Goldilocks zone \citep{snell2025scaling, loo2025reevaluating}.

\section{Conclusion}\label{sec:conclusion}

We evaluated SICA across seven models (7B--32B) on four reasoning domains ($N > 2{,}400$). Self-extracted constraints help only in a narrow Goldilocks zone ($\sim$50--55\% SC), with three failure modes outside it: confirmation bias at high accuracy (Type A, eight conditions, all n.s.), harmful noise at very low accuracy (Type C, $\Delta = -4.67$\,pp), and non-formalizable domains (Type B). Oracle experiments ($+14.22$\,pp FOLIO, $+11.50$\,pp ProofWriter) confirm aggregation works with discriminative constraints. Six remediation strategies, including ICL with gold FOL examples, all fail to widen this zone.

For deployment, $C_0$ and SC accuracy form a two-dimensional diagnostic: low $C_0$ renders SICA degenerate; high $C_0$ with high SC triggers Type A; high $C_0$ with very low SC risks Type C; only moderate SC ($\sim$50--55\%) is favorable, capturing 34.5\% of the oracle ceiling. Trained extractors and external provers remain viable paths to close this gap.

\section{Prompt Templates}
\label{app:prompts}

SICA uses domain-specific prompt templates for constraint extraction: one for mathematical reasoning (GSM8K, AIME) and one for logical reasoning (ProofWriter, FOLIO). Both share the same system prompt. The LLM is called with temperature $T{=}0.3$, max tokens $1024$, and structured JSON output mode. Up to 6 traces are processed in parallel via thread pooling, with 2 retries on failure (exponential backoff, base 0.5s).

\paragraph{System Prompt.}

\begin{lstlisting}
You are a constraint extraction tool. Output ONLY
valid JSON. Do NOT solve problems, reason about
correctness, or think step-by-step. Extract
constraints from the given trace exactly as stated.
\end{lstlisting}

\paragraph{Mathematical Constraint Extraction (EXTRACTION\_PROMPT).}

Used for GSM8K and AIME datasets. The placeholder \texttt{\{trace\}} is replaced with the reasoning trace at runtime.

\begin{lstlisting}
Extract mathematical constraints from this reasoning
trace as a JSON object.

Rules:
- type: "equation", "inequality", or "predicate"
- expression: human-readable, e.g. "x + y == 14"
- z3_formula: a single comparison expression in
  Python Z3 syntax
- source_step: step number where the constraint
  appears
- Use variable names from the trace

z3_formula MUST follow these rules:
- Allowed operators: ==, !=, <, >, <=, >=, +, -, *,
  /, **, %
- Use individual named variables: a1, a2, a3...
  NOT arrays a[1] or sets A
- Expand all sums explicitly:
  "a1 + a2 + a3 == 55" NOT "sum([a1,a2,a3])"
- NO Python builtins: sum(), len(), max(), min(),
  list(), set(), range(), int()
- Each z3_formula must be exactly ONE comparison
  (==, !=, <, >, <=, >=)
- For multiple values, write separate constraints
  for each

Output ONLY the JSON below, nothing else:
{"constraints": [{"type": "equation",
  "expression": "x + y == 14",
  "z3_formula": "x + y == 14",
  "source_step": 1}],
 "answer": "final_answer",
 "variables": ["x", "y"]}

Trace:
{trace}
\end{lstlisting}

\paragraph{Logical Constraint Extraction (LOGIC\_EXTRACTION\_PROMPT).}

Used for ProofWriter and FOLIO datasets.

\begin{lstlisting}
IMPORTANT: You are an EXTRACTION tool, NOT a problem
solver.
- Do NOT re-solve or re-reason about the problem.
- Do NOT verify whether the trace's reasoning is
  correct.
- ONLY extract the logical constraints that are
  explicitly stated or used in the trace below.
- Output ONLY the JSON object, nothing else.

Extract logical constraints from this reasoning trace
about a logic problem.

The problem has facts (base assertions), rules
(grounded implications), and derived conclusions.
Convert each into a Z3 boolean formula.

Variable naming:
- Unary property: property_entity
  (e.g., kind_anne, red_charlie, round_fiona)
- Binary relation: relation_subject_object
  (e.g., eats_bear_squirrel, likes_lion_cat)
- Use lowercase with underscores only

Constraint types:
- "fact": a given assertion,
  e.g., kind_anne == True
- "rule": a grounded implication over specific
  entities, e.g., Implies(kind_anne, nice_anne)
- "derived": an inferred conclusion from facts +
  rules, e.g., nice_anne == True

Z3 operators:
- Implies(a, b) for if-then rules
- And(a, b, ...) for conjunctive conditions
- Or(a, b, ...) for disjunctive conditions
- Not(a) for negation
- == True / == False for boolean assertions

Output ONLY the JSON below, nothing else:
{"constraints": [{"type": "fact",
  "expression": "kind(anne)",
  "z3_formula": "kind_anne == True",
  "source_step": 1}],
 "answer": "True or False or Unknown",
 "variables": ["kind_anne"]}

Trace:
{trace}
\end{lstlisting}

\paragraph{Output Schema.}

Both prompts produce a JSON object with the following structure:

\begin{lstlisting}
{
  "constraints": [
    {
      "type": "<equation|inequality|predicate>
               or <fact|rule|derived>",
      "expression": "<human-readable description>",
      "z3_formula": "<Z3-compatible expression>",
      "source_step": <integer>
    }
  ],
  "answer": "<final answer string>",
  "variables": ["<var1>", "<var2>", "..."]
}
\end{lstlisting}

The pipeline additionally injects an \texttt{answer\_assertion} constraint per trace (not produced by the LLM):

\begin{lstlisting}
{"type": "answer_assertion",
 "expression": "answer is <ans>",
 "z3_formula": "__sica_answer_<ans> == True",
 "source_step": -1}
\end{lstlisting}

\paragraph{Prompt Selection Logic.}

Domain assignment is determined by dataset: FOLIO and ProofWriter use \textsc{Logic\_Extraction\_Prompt}; GSM8K, AIME, StrategyQA, and ARC-Challenge use \textsc{Extraction\_Prompt}. StrategyQA and ARC-Challenge are assigned to the mathematical prompt because their reasoning structure does not involve formal logic predicates or implications, despite StrategyQA producing boolean answers.


\section{Z3 MaxSAT Evaluation Pseudocode}
\label{app:z3-pseudocode}

Algorithm~\ref{alg:maxsat} describes the Z3 MaxSAT solving procedure. Algorithm~\ref{alg:scorer} describes the source-trace attribution scoring.

Domain constraint variables (e.g., \texttt{x + y == 14}) and answer assertion variables (e.g., \texttt{\_\_sica\_answer\_42 == True}) are logically independent in the Z3 formulation. Discriminative signal arises solely from conflicts among domain constraints: when traces supporting different answers produce mutually contradictory constraints, the solver excludes the lower-weight subset, and the scorer penalizes the corresponding answers.

\begin{algorithm}[h]
\caption{Z3 Weighted Partial MAX-SAT}
\label{alg:maxsat}
\begin{algorithmic}[1]
\Require Deduplicated constraint set $\mathcal{C} = \{(c_m, w_m, S_m)\}_{m=1}^M$ where $c_m$ is a Z3 formula, $w_m$ is weight, $S_m$ is the set of source trace indices
\Ensure Partition $(\mathcal{C}^*, \mathcal{C}^{\setminus})$ where $\mathcal{C}^*$ is the max-weight satisfiable subset
\State $\textit{opt} \gets \textsc{Z3.Optimize()}$
\For{$m = 1, \ldots, M$}
    \State $b_m \gets$ fresh Boolean indicator
    \State $\textit{opt}.\textsc{Add}(b_m \Rightarrow c_m)$ \Comment{soft clause guarded by indicator}
    \State $\textit{opt}.\textsc{AddSoft}(b_m,\; \text{weight}=w_m)$
\EndFor
\State $\textit{result} \gets \textit{opt}.\textsc{Check}()$
\State $\textit{model} \gets \textit{opt}.\textsc{Model}()$
\State $\mathcal{C}^* \gets \{(c_m, w_m, S_m) : \textit{model}(b_m) = \top\}$
\State $\mathcal{C}^{\setminus} \gets \mathcal{C} \setminus \mathcal{C}^*$
\State \Return $(\mathcal{C}^*, \mathcal{C}^{\setminus})$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[h]
\caption{Source-Trace Attribution Scoring}
\label{alg:scorer}
\begin{algorithmic}[1]
\Require Satisfied set $\mathcal{C}^*$, excluded set $\mathcal{C}^{\setminus}$, candidate answers $\mathcal{A}$, trace-answer mapping $\tau: \text{trace\_idx} \to a$, penalty weight $\alpha$
\Ensure Score $s(a)$ for each $a \in \mathcal{A}$
\For{each $a \in \mathcal{A}$}
    \State $T_a \gets \{i : \tau(i) = a\}$ \Comment{trace indices producing answer $a$}
    \State $\textit{pos}(a) \gets \sum_{(c,w,S) \in \mathcal{C}^*} w \cdot \mathbf{1}[S \cap T_a \neq \emptyset]$
    \State $\textit{neg}(a) \gets \sum_{(c,w,S) \in \mathcal{C}^{\setminus}} w \cdot \mathbf{1}[S \cap T_a \neq \emptyset]$
    \State $s(a) \gets \textit{pos}(a) - \alpha \cdot \textit{neg}(a)$
\EndFor
\State \Return $a^* = \arg\max_{a \in \mathcal{A}} s(a)$
\end{algorithmic}
\end{algorithm}


